#include "include/safe_fs.hpp"
#include "include/heap.hpp"
#include "include/quality.hpp"

namespace {
static Fat32Volume* gVolume=nullptr;
static SafeFsStats g{};
static constexpr const char* JOURNAL="/SYSTEM/ZNTTXN.TXT";
static size_t len(const char*s){size_t n=0;if(s)while(s[n])++n;return n;}
static void append(char*d,size_t cap,const char*s){size_t n=len(d),i=0;if(!d||!cap||!s)return;while(n+1<cap&&s[i])d[n++]=s[i++];d[n]=0;}
static void copy(char*d,size_t cap,const char*s){if(!d||!cap)return;size_t i=0;if(s)while(i+1<cap&&s[i]){d[i]=s[i];++i;}d[i]=0;}
static bool eqci(const char*a,const char*b){if(!a||!b)return false;while(*a&&*b){char x=*a++,y=*b++;if(x>='a'&&x<='z')x-=32;if(y>='a'&&y<='z')y-=32;if(x!=y)return false;}return *a==0&&*b==0;}
static bool sibling(const char*path,const char*name,char*out,size_t cap){if(!path||!name||!out||!cap)return false;size_t n=len(path),slash=n;while(slash&&path[slash-1]!='/'&&path[slash-1]!='\\')--slash;out[0]=0;for(size_t i=0;i<slash&&i+1<cap;++i){char t[2]={path[i],0};append(out,cap,t);}append(out,cap,name);return out[0]!=0;}
static bool verify_file(const char*path,const void*data,size_t size){if(size==0){uint8_t dummy=0;size_t got=0;return fat32_read_file(*gVolume,path,&dummy,0,got)&&got==0;}void*mem=kmalloc(size);if(!mem)return false;size_t got=0;bool ok=fat32_read_file(*gVolume,path,mem,size,got)&&got==size;if(ok){const uint8_t*a=(const uint8_t*)data,*b=(const uint8_t*)mem;for(size_t i=0;i<size;++i)if(a[i]!=b[i]){ok=false;break;}}kfree(mem);return ok;}
struct FindCtx{const char*name;bool found;};
static void find_cb(const Fat32DirEntry&e,void*ctx){auto*c=static_cast<FindCtx*>(ctx);if(eqci(e.name,c->name))c->found=true;}
static bool path_exists(const char*path){if(!gVolume||!path||!*path)return false;char parent[1024]{},name[256]{};size_t n=len(path),slash=n;while(slash&&path[slash-1]!='/'&&path[slash-1]!='\\')--slash;if(slash==0){copy(parent,sizeof(parent),"/");copy(name,sizeof(name),path);}else{size_t pn=slash;while(pn>1&&(path[pn-1]=='/'||path[pn-1]=='\\'))--pn;size_t i=0;for(;i<pn&&i+1<sizeof(parent);++i)parent[i]=path[i];parent[i]=0;if(!parent[0])copy(parent,sizeof(parent),"/");copy(name,sizeof(name),path+slash);}FindCtx c{name,false};if(!fat32_list_directory(*gVolume,parent,find_cb,&c))return false;return c.found;}
static bool write_journal(const char*target,const char*temp,const char*backup,uint32_t stage){char b[4096]{};append(b,sizeof(b),"TARGET=");append(b,sizeof(b),target);append(b,sizeof(b),"\r\nTEMP=");append(b,sizeof(b),temp);append(b,sizeof(b),"\r\nBACKUP=");append(b,sizeof(b),backup);append(b,sizeof(b),"\r\nSTAGE=");char s[2]={char('0'+(stage%10)),0};append(b,sizeof(b),s);append(b,sizeof(b),"\r\n");fat32_delete_file(*gVolume,JOURNAL);if(!fat32_create_file(*gVolume,JOURNAL)||!fat32_write_file(*gVolume,JOURNAL,b,len(b)))return false;if(gVolume->device->flush){++g.flushes;if(!block_flush(gVolume->device))return false;}++g.journalWrites;return true;}
static void clear_journal(){fat32_delete_file(*gVolume,JOURNAL);if(gVolume&&gVolume->device&&gVolume->device->flush){++g.flushes;block_flush(gVolume->device);}}
static bool field(const char*buf,const char*key,char*out,size_t cap){size_t kl=len(key);for(size_t i=0;buf[i];++i){size_t j=0;while(j<kl&&buf[i+j]==key[j])++j;if(j==kl){i+=kl;size_t o=0;while(buf[i]&&buf[i]!='\r'&&buf[i]!='\n'&&o+1<cap)out[o++]=buf[i++];out[o]=0;return true;}}return false;}
}

void safe_fs_init(Fat32Volume* volume){gVolume=volume;g={};g.volumeHealthy=volume&&volume->stats.mounted&&volume->device&&volume->device->read;if(g.volumeHealthy)safe_fs_recover_pending();}
bool safe_fs_check_volume(){++g.bootChecks;if(!gVolume||!gVolume->stats.mounted||!gVolume->device||!gVolume->device->read){g.volumeHealthy=false;return false;}if(gVolume->stats.bytesPerSector<512||gVolume->stats.bytesPerSector>4096||!gVolume->stats.sectorsPerCluster||gVolume->stats.rootCluster<2||gVolume->stats.fatCount==0){g.volumeHealthy=false;return false;}struct C{uint32_t n;};C c{};bool ok=fat32_list_directory(*gVolume,"/",[](const Fat32DirEntry&,void*ctx){++static_cast<C*>(ctx)->n;},&c);Fat32CheckStats check{};ok=ok&&fat32_check_volume(*gVolume,check)&&check.healthy;if(gVolume->device->flush){++g.flushes;ok=ok&&block_flush(gVolume->device);}g.volumeHealthy=ok;return ok;}
bool safe_fs_recover_pending(){if(!gVolume||!gVolume->stats.mounted)return false;char b[4096]{};size_t got=0;if(!fat32_read_file(*gVolume,JOURNAL,b,sizeof(b)-1,got))return true;b[got]=0;char target[1024]{},temp[1024]{},backup[1024]{};if(!field(b,"TARGET=",target,sizeof(target))||!field(b,"TEMP=",temp,sizeof(temp))||!field(b,"BACKUP=",backup,sizeof(backup))){clear_journal();++g.failures;return false;}bool changed=false;if(path_exists(target)){fat32_delete_file(*gVolume,temp);fat32_delete_file(*gVolume,backup);changed=true;}else if(path_exists(backup)){fat32_delete_file(*gVolume,temp);if(fat32_rename(*gVolume,backup,target))changed=true;}else if(path_exists(temp)){if(fat32_rename(*gVolume,temp,target))changed=true;}clear_journal();if(changed)++g.recoveredTransactions;return true;}
bool safe_fs_atomic_write(const char*path,const void*data,size_t size){if(!gVolume||!gVolume->device||!gVolume->device->write||!path||(size&&!data)){++g.failures;return false;}char temp[1024]{},backup[1024]{};if(!sibling(path,"ZNTTMP.TMP",temp,sizeof(temp))||!sibling(path,"ZNTBAK.BAK",backup,sizeof(backup))){++g.failures;return false;}safe_fs_recover_pending();fat32_delete_file(*gVolume,temp);fat32_delete_file(*gVolume,backup);if(!write_journal(path,temp,backup,1)){++g.failures;return false;}if(!fat32_create_file(*gVolume,temp)||!fat32_write_file(*gVolume,temp,data,size)){fat32_delete_file(*gVolume,temp);clear_journal();++g.failures;quality_record_recoverable_error();return false;}if(!verify_file(temp,data,size)){fat32_delete_file(*gVolume,temp);clear_journal();++g.failures;quality_record_recoverable_error();return false;}++g.verifiedWrites;const bool hadOld=fat32_rename(*gVolume,path,backup);if(!write_journal(path,temp,backup,2)){if(hadOld)fat32_rename(*gVolume,backup,path);fat32_delete_file(*gVolume,temp);clear_journal();++g.failures;return false;}if(!fat32_rename(*gVolume,temp,path)){if(hadOld){fat32_rename(*gVolume,backup,path);++g.rollbacks;}fat32_delete_file(*gVolume,temp);clear_journal();++g.failures;quality_record_recoverable_error();return false;}write_journal(path,temp,backup,3);if(hadOld)fat32_delete_file(*gVolume,backup);clear_journal();if(gVolume->device->flush){++g.flushes;if(!block_flush(gVolume->device)){++g.failures;return false;}}++g.atomicWrites;return true;}
bool safe_fs_copy_file(const char*src,const char*dst,bool removeSource){if(!gVolume||!src||!dst)return false;bool ok=removeSource?fat32_move_file(*gVolume,src,dst):fat32_copy_file(*gVolume,src,dst);if(ok)++g.atomicWrites;else{++g.failures;quality_record_recoverable_error();}return ok;}
bool safe_fs_copy_tree(const char*src,const char*dst,bool removeSource){if(!gVolume||!src||!dst)return false;bool ok=removeSource?fat32_move_tree(*gVolume,src,dst):fat32_copy_tree(*gVolume,src,dst);if(ok){if(removeSource)++g.treeMoves;else ++g.treeCopies;}else{++g.failures;quality_record_recoverable_error();}return ok;}
bool safe_fs_delete_tree(const char*path){if(!gVolume||!path)return false;bool ok=fat32_delete_tree(*gVolume,path);if(ok)++g.treeDeletes;else{++g.failures;quality_record_recoverable_error();}return ok;}
SafeFsStats safe_fs_stats(){return g;}
